import { test, expect } from '@playwright/test';

test.describe('Lazy-loaded Components - Smooth Appearance', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/lazy-load-demo');
  });

  test('should load lazy components smoothly without layout shift', async ({ page }) => {
    // Verify initial page content is visible
    const header = page.getByRole('banner');
    await expect(header).toBeVisible();

    // Verify lazy component placeholder is visible
    const placeholder = page.getByText('Lazy Component Placeholder');
    await expect(placeholder).toBeVisible();

    // Verify lazy component is not yet visible
    const lazyComponent = page.getByText('Lazy Component Content');
    await expect(lazyComponent).not.toBeVisible();

    // Scroll to trigger lazy loading
    await page.evaluate(() => window.scrollTo(0, 800));

    // Wait for lazy component to load
    await page.waitForLoadState('networkidle');

    // Verify lazy component is now visible
    await expect(lazyComponent).toBeVisible();

    // Verify layout shift did not occur by checking element positions
    const placeholderBox = page.locator('[data-testid="placeholder-box"]');
    const lazyComponentBox = page.locator('[data-testid="lazy-component-box"]');

    const placeholderRect = await placeholderBox.boundingBox();
    const lazyRect = await lazyComponentBox.boundingBox();

    expect(placeholderRect.y).toBeLessThan(lazyRect.y);
    expect(placeholderRect.height).toBeGreaterThan(0);
    expect(lazyRect.height).toBeGreaterThan(0);

    // Verify smooth transition animation
    const transition = page.locator('[data-testid="lazy-component-transition"]');
    await expect(transition).toBeVisible();

    // Verify transition class is applied
    const hasTransitionClass = await transition.evaluate((el) => el.classList.contains('transition-active'));
    expect(hasTransitionClass).toBe(true);
  });

  test('should handle multiple lazy components and load them sequentially', async ({ page }) => {
    // Verify first lazy component placeholder is visible
    const placeholder1 = page.getByText('Lazy Component Placeholder 1');
    await expect(placeholder1).toBeVisible();

    // Scroll to trigger first lazy component
    await page.evaluate(() => window.scrollTo(100, 500));
    await page.waitForLoadState('networkidle');

    // Verify first lazy component is visible
    const lazyComponent1 = page.getByText('Lazy Component Content 1');
    await expect(lazyComponent1).toBeVisible();

    // Scroll further to trigger second lazy component
    await page.evaluate(() => window.scrollTo(100, 1500));
    await page.waitForLoadState('networkidle');

    // Verify second lazy component is visible
    const lazyComponent2 = page.getByText('Lazy Component Content 2');
    await expect(lazyComponent2).toBeVisible();

    // Verify both components are visible and not overlapping
    const lazyBox1 = page.locator('[data-testid="lazy-component-box-1"]');
    const lazyBox2 = page.locator('[data-testid="lazy-component-box-2"]');

    const rect1 = await lazyBox1.boundingBox();
    const rect2 = await lazyBox2.boundingBox();

    expect(rect1.y).toBeLessThan(rect2.y);
    expect(rect1.height).toBeGreaterThan(0);
    expect(rect2.height).toBeGreaterThan(0);

    // Verify smooth transition for both
    const transition1 = page.locator('[data-testid="lazy-component-transition-1"]');
    const transition2 = page.locator('[data-testid="lazy-component-transition-2"]');

    const hasTransitionClass1 = await transition1.evaluate((el) => el.classList.contains('transition-active'));
    const hasTransitionClass2 = await transition2.evaluate((el) => el.classList.contains('transition-active'));

    expect(hasTransitionClass1).toBe(true);
    expect(hasTransitionClass2).toBe(true);
  });
});
